return ['domain'=>'publishpress-hubn%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'ru_RU','project-id-version'=>'PublishPress Hub 1.2.0','pot-creation-date'=>'2026-11-16T12:00:34+00:00','po-revision-date'=>'2026-11-16 12:44+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'PublishPress Hub','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'Централизованный управляющий центр для всех плагинов PublishPress - устанавливайте, обновляйте и управляйте лицензиями с одной панели управления.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'Пожалуйста, подождите, пока мы загружаем демонстрацию компонентов...','AI Connections'=>'AI Connections','Please wait while we load AI connections...'=>'Пожалуйста, подождите, пока мы загружаем AI соединения...','Please wait while we load the plugins dashboard...'=>'Пожалуйста, подождите, пока мы загружаем панель управления плагинами...','Settings'=>'Настройки','Please wait while we load the settings page...'=>'Пожалуйста, подождите, пока мы загружаем страницу настроек...','You do not have sufficient permissions to access this page.'=>'У вас недостаточно прав для доступа к этой странице.','Welcome'=>'Добро пожаловать','Please wait while we load the welcome page...'=>'Пожалуйста, подождите, пока мы загружаем страницу приветствия...','Language pack has not been checked yet.'=>'Языковой пакет еще не был проверен.','Site locale is English. No language pack is downloaded.'=>'Язык сайта - английский. Языковой пакет не загружен.','No language packs are registered.'=>'Языковые пакеты не зарегистрированы.','Language pack directory is not available.'=>'Каталог языкового пакета недоступен.','Language pack for %1$s (%2$s) matches %3$s.'=>'Языковой пакет для %1$s (%2$s) соответствует %3$s.','Language pack for %1$s (%2$s) installed for %3$s.'=>'Языковой пакет для %1$s (%2$s) установлен для %3$s.','Language pack URL was rejected.'=>'URL языкового пакета был отклонен.','Language pack download failed for %1$s (%2$s). The installed pack was left in place.'=>'Не удалось загрузить языковой пакет для %1$s (%2$s). Установленный пакет оставлен на месте.','Language pack could not be unpacked.'=>'Языковой пакет не может быть распакован.','Language pack is missing a catalog file. The installed pack was left in place.'=>'В языковом пакете отсутствует файл каталога. Установленный пакет оставлен на месте.','Language pack JSON catalog is invalid. The installed pack was left in place.'=>'JSON каталог языкового пакета недействителен. Установленный пакет оставлен на месте.','Language pack could not be stored. The installed pack was left in place.'=>'Языковой пакет не может быть сохранен. Установленный пакет оставлен на месте.','Language pack PHP catalog could not be built. The installed pack was left in place.'=>'PHP каталог языкового пакета не может быть создан. Установленный пакет оставлен на месте.','Warning: The license for %1$s has expired. %2$s'=>'Внимание: Лицензия для %1$s истекла. %2$s','Manage licenses'=>'Управление лицензиями','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'Внимание: У %1$d плагина(ов) истекли лицензии: %2$s. %3$s','The license server accepted your key, but this site could not save its active license. Please contact support and mention this message.'=>'Сервер лицензий принял ваш ключ, но этот сайт не смог сохранить свою активную лицензию. Пожалуйста, свяжитесь с поддержкой и укажите это сообщение.','PublishPress actions for %s. These tools apply only to this site. If several sites are connected and the requested site is unclear, ask which site to use before calling a tool. Confirm the target site before changing site data.'=>'Действия PublishPress для %s. Эти инструменты применяются только к этому сайту. Если несколько сайтов подключены и запрашиваемый сайт неясен, уточните, какой сайт использовать перед вызовом инструмента. Подтвердите целевой сайт перед изменением данных сайта.','WordPress version'=>'Версия WordPress','MCP Adapter version'=>'Версия адаптера MCP','Not active'=>'Неактивно','HTTPS'=>'HTTPS','Available'=>'Доступно','Required'=>'Обязательно','Application passwords'=>'Пароли приложений','Unavailable; check WordPress or security plugin settings'=>'Недоступно; проверьте настройки WordPress или плагина безопасности','Registered actions'=>'Зарегистрированные действия','Selected actions exposed'=>'Выбранные действия открыты','Changes saved.'=>'Изменения сохранены.','Changes saved. Restart your AI app or refresh its PublishPress connection to update the available actions.'=>'Изменения сохранены. Перезапустите ваше AI-приложение или обновите его соединение с PublishPress, чтобы обновить доступные действия.','Changes saved. Connect your AI app to continue.'=>'Изменения сохранены. Подключите ваше AI-приложение, чтобы продолжить.','Changes saved. Select at least one available action to continue.'=>'Изменения сохранены. Выберите хотя бы одно доступное действие, чтобы продолжить.','Update WordPress to continue'=>'Обновите WordPress, чтобы продолжить','WordPress 6.9 or newer is required.'=>'Требуется WordPress 6.9 или новее.','Open WordPress updates'=>'Открыть обновления WordPress','Install the MCP Adapter plugin'=>'Установите плагин MCP Adapter','Install the official WordPress MCP Adapter plugin to connect your AI service.'=>'Установите официальный плагин MCP Adapter для WordPress, чтобы подключить вашу AI-службу.','Manage plugins'=>'Управление плагинами','Set up MCP Adapter'=>'Настроить MCP Adapter','Use HTTPS to connect your AI'=>'Используйте HTTPS для подключения вашего AI','Both WordPress and site addresses must use HTTPS.'=>'Как WordPress, так и адреса сайта должны использовать HTTPS.','Open site settings'=>'Открыть настройки сайта','Add a PublishPress plugin with AI actions'=>'Добавить плагин PublishPress с действиями AI','You don\'t have any PublishPress plugins installed that support AI actions yet.'=>'У вас еще нет установленных плагинов PublishPress, которые поддерживают действия AI.','Open PublishPress plugins'=>'Открыть плагины PublishPress','Allow application passwords for your account'=>'Разрешить пароли приложений для вашей учетной записи','Create an application password in your WordPress profile for assisted or manual setup.'=>'Создайте пароль приложения в вашем профиле WordPress для помощи в настройке или ручной настройки.','Application passwords are unavailable for your account. HTTPS or security plugin settings may need attention.'=>'Пароли приложений недоступны для вашей учетной записи. Возможно, потребуется обратить внимание на настройки HTTPS или плагина безопасности.','Open application passwords'=>'Открыть пароли приложений','PASTE_YOUR_APPLICATION_PASSWORD_HERE'=>'ВСТАВЬТЕ_ВАШ_ПАРОЛЬ_ПРИЛОЖЕНИЯ_ЗДЕСЬ','Ask my AI to help'=>'Попросите моего AI помочь','Recommended. Ask your AI for a setup script to run on your computer.'=>'Рекомендуется. Попросите вашего AI предоставить скрипт настройки для выполнения на вашем компьютере.','Connect my AI app to PublishPress. Create a setup script and give me the exact terminal command to run it.

1. Ask me to select my AI app and OS (Windows, macOS or Linux). Use interactive choices if available, otherwise numbered options.
2. Create the script using your file tools. Request the specific permission if needed. If you cannot write locally, attach a downloadable script. Only fall back to code with save instructions when neither is possible. Use PowerShell on Windows and an appropriate script on macOS or Linux. Do not stop at explaining access limitations or provide only JSON.
3. Configure this local stdio server:
Name: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Read WP_API_PASSWORD through a hidden terminal prompt.
Hub write access: %5$s. Only individually selected actions are exposed.
4. Check Node.js and npx. If missing, link to the official installer and tell me to reopen the terminal. Back up existing settings. Use a JSON/TOML parser or supported client command to merge only this server, preserving other settings and sites. Stop on invalid configuration or a conflicting endpoint. If replacing an old PublishPress desktop extension for this site, guide me to disable only that extension to avoid duplicate connections. Quote paths and values safely.
5. Give brief run, restart and approval instructions. Verify through the connection or give me a prompt to test in the app: confirm the site URL, list actual tools and perform a read-only lookup. Report whether write tools are available. If expected write tools are missing, ask me to check Allow actions that change site data and the selected actions in Hub, then refresh the connection. Do not claim success from saved configuration alone. Do not test writes during setup. Clarify the target site when ambiguous and ask for review before changing site data.'=>'Подключите мое AI-приложение к PublishPress. Создайте скрипт настройки и дайте мне точную команду терминала для его выполнения.

1. Попросите меня выбрать мое AI-приложение и ОС (Windows, macOS или Linux). Используйте интерактивные варианты, если доступны, в противном случае нумерованные варианты.
2. Создайте скрипт с использованием ваших инструментов файловой системы. Запросите конкретное разрешение, если это необходимо. Если вы не можете записывать локально, прикрепите загружаемый скрипт. Переходите к коду с инструкциями по сохранению только в том случае, если ни один из вариантов невозможен. Используйте PowerShell на Windows и соответствующий скрипт на macOS или Linux. Не останавливайтесь на объяснении ограничений доступа и не предоставляйте только JSON.
3. Настройте этот локальный сервер stdio:
Имя: %3$s
Отображаемое имя: %4$s
Команда: npx
Аргументы: -y @automattic/mcp-wordpress-remote@latest
Среда: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Читать WP_API_PASSWORD через скрытый запрос терминала.
Доступ на запись в Hub: %5$s. Только индивидуально выбранные действия открыты.
4. Проверьте наличие Node.js и npx. Если отсутствуют, дайте ссылку на официальный установщик и скажите мне снова открыть терминал. Создайте резервную копию существующих настроек. Используйте парсер JSON/TOML или поддерживаемую команду клиента, чтобы объединить только этот сервер, сохраняя другие настройки и сайты. Остановитесь на недействительной конфигурации или конфликтующем конечном пункте. Если заменяете старое расширение PublishPress для рабочего стола для этого сайта, направьте меня отключить только это расширение, чтобы избежать дублирующих соединений. Безопасно цитируйте пути и значения.
5. Дайте краткие инструкции по запуску, перезапуску и утверждению. Проверьте через соединение или дайте мне подсказку для тестирования в приложении: подтвердите URL сайта, перечислите фактические инструменты и выполните запрос только для чтения. Сообщите, доступны ли инструменты записи. Если ожидаемые инструменты записи отсутствуют, попросите меня проверить разрешения на действия, изменяющие данные сайта, и выбранные действия в Hub, затем обновите соединение. Не утверждайте успех только на основании сохраненной конфигурации. Не тестируйте записи во время настройки. Уточните целевой сайт, когда это неясно, и попросите обзор перед изменением данных сайта.</source>
<t i="30">включено','disabled'=>'выключено','Set up manually'=>'Настроить вручную','Copy the configuration into your MCP client.'=>'Скопируйте конфигурацию в ваш клиент MCP.','Actions available through PublishPress Hub.'=>'Действия доступны через PublishPress Hub.','List WordPress users'=>'Список пользователей WordPress','Find users by name or role. The optional primitive capability filter checks effective access within each candidate page. Visit all total_pages even when a filtered page is empty. No email addresses or secrets are returned.'=>'Найдите пользователей по имени или роли. Дополнительный фильтр примитивных возможностей проверяет эффективный доступ в каждой кандидатной странице. Посетите все total_pages, даже когда отфильтрованная страница пуста. Адреса электронной почты или секреты не возвращаются.','Get WordPress user capabilities'=>'Получить возможности пользователей WordPress','Resolve exactly one user_id or username and return their identity, roles and effective primitive capabilities. Never guess a user ID. Object-specific permissions require a separate check for that object.'=>'Разрешите точно один user_id или имя пользователя и верните их личность, роли и эффективные примитивные возможности. Никогда не угадывайте ID пользователя. Разрешения, специфичные для объекта, требуют отдельной проверки для этого объекта.','Find WordPress content'=>'Найти контент WordPress','Search readable posts, pages or a REST-enabled custom post type. Returns actual IDs, titles and permalinks. Use post_type=page for pages. Resolve ambiguous titles before using a URL. Default status is publish. Private and draft requests enforce WordPress permissions.'=>'Искать читаемые посты, страницы или посты с поддержкой REST. Возвращает фактические ID, заголовки и постоянные ссылки. Используйте post_type=page для страниц. Уточняйте неоднозначные заголовки перед использованием URL. Статус по умолчанию - опубликовано. Запросы на частные и черновики соблюдают разрешения WordPress.','List WordPress post types'=>'Список типов постов WordPress','List readable REST-enabled post types and the capability names used for each type. Use these names for content lookups and permission questions.'=>'Список читаемых типов постов с поддержкой REST и названий возможностей, используемых для каждого типа. Используйте эти названия для поиска контента и вопросов разрешений.','WordPress'=>'WordPress','Create WordPress user'=>'Создать пользователя WordPress','Create a new user account with a known username, email and one editable role. Ask for missing details. WordPress validates role assignment permissions. MCP rejects administrator and any role granting administrator-level capabilities. A password is generated privately. By default WordPress emails the user a password setup link. Never guess an email or request a password in chat.'=>'Создайте новую учетную запись пользователя с известным именем пользователя, адресом электронной почты и одной изменяемой ролью. Запросите недостающие данные. WordPress проверяет разрешения на назначение ролей. MCP отклоняет администратора и любую роль, предоставляющую возможности уровня администратора. Пароль генерируется приватно. По умолчанию WordPress отправляет пользователю ссылку для настройки пароля по электронной почте. Никогда не угадывайте адрес электронной почты и не запрашивайте пароль в чате.','Create WordPress content'=>'Создать контент WordPress','Create a post, page or REST-enabled custom post type. Use post_type=page for pages. Defaults to draft. Publish or schedule only when requested. WordPress checks creation, publishing and author-assignment permissions. Returns the actual ID and permalink.'=>'Создайте запись, страницу или пользовательский тип записи с поддержкой REST. Используйте post_type=page для страниц. По умолчанию черновик. Публикуйте или планируйте только по запросу. WordPress проверяет разрешения на создание, публикацию и назначение автора. Возвращает фактический ID и постоянную ссылку.','Update WordPress content'=>'Обновить контент WordPress','Edit an existing post, page or REST-enabled custom post by its verified ID. Find content first if the ID is unknown. Only supplied fields change. WordPress checks object, publishing and author-assignment permissions. No deletion, arbitrary metadata or options are supported.'=>'Отредактируйте существующую запись, страницу или пользовательский пост с поддержкой REST по его проверенному ID. Сначала найдите контент, если ID неизвестен. Меняются только предоставленные поля. WordPress проверяет разрешения на объект, публикацию и назначение автора. Удаление, произвольные метаданные или параметры не поддерживаются.','Use the exact input types shown in discovery.'=>'Используйте точно такие же типы ввода, как показано в обнаружении.','You cannot list users.'=>'Вы не можете перечислить пользователей.','Provide either a user ID or an exact username.'=>'Укажите либо ID пользователя, либо точное имя пользователя.','No matching user belongs to this site.'=>'Нет соответствующего пользователя, принадлежащего этому сайту.','You cannot inspect this user.'=>'Вы не можете просмотреть этого пользователя.','Choose a REST-enabled post type.'=>'Выберите тип записи с поддержкой REST.','This post type does not support content lookup.'=>'Этот тип записи не поддерживает поиск контента.','MCP tools cannot create users with administrator-level access. Use the WordPress Users screen for this change.'=>'Инструменты MCP не могут создавать пользователей с доступом уровня администратора. Используйте экран пользователей WordPress для этого изменения.','Provide at least one content field to update.'=>'Укажите хотя бы одно поле контента для обновления.','Choose an existing REST-enabled post type.'=>'Выберите существующий тип записи с поддержкой REST.','This post type does not support content writes.'=>'Этот тип записи не поддерживает запись контента.','You cannot perform this operation.'=>'Вы не можете выполнить эту операцию.','Object must be loaded before initializing.'=>'Объект должен быть загружен перед инициализацией.','This license key is managed in wp-config.php and cannot be edited from the Hub.'=>'Этот лицензионный ключ управляется в wp-config.php и не может быть отредактирован из Центра.','No license key found'=>'Лицензионный ключ не найден','This license key is managed in wp-config.php and cannot be deactivated from the Hub.'=>'Этот лицензионный ключ управляется в wp-config.php и не может быть деактивирован из Центра.','Invalid conflict resolution request.'=>'Недействительный запрос на разрешение конфликта.','The selected plugin is not available for activation.'=>'Выбранный плагин недоступен для активации.','Cleanup was stopped because the selected plugin is not active or the other version is still loaded. Neither copy was deleted.'=>'Очистка была остановлена, потому что выбранный плагин не активен или другая версия все еще загружена. Ни одна копия не была удалена.','The selected plugin is active, but the other version could not be removed. Please remove it from the Plugins screen.'=>'Выбранный плагин активен, но другую версию не удалось удалить. Пожалуйста, удалите ее из экрана плагинов.','The selected plugin is no longer active. Please reactivate it from the Plugins screen.'=>'Выбранный плагин больше не активен. Пожалуйста, повторно активируйте его из экрана плагинов.','No existing license key was found for this plugin.'=>'Не найдено существующего лицензионного ключа для этого плагина.','Database Tables'=>'Таблицы базы данных','PublishPress Plugins'=>'Плагины PublishPress','PublishPress Hub Debug Log'=>'Журнал отладки PublishPress Hub','Debug Log'=>'Журнал отладки','The debug log is empty.'=>'Журнал отладки пуст.','Version'=>'Версия','Debug Mode'=>'Режим отладки','Enabled'=>'Включен','Disabled'=>'Выключен','Generated At'=>'Сгенерировано в','Plugins'=>'Плагины','No PublishPress plugins found.'=>'Плагины PublishPress не найдены.','Tables'=>'Таблицы','No database table information was available.'=>'Информация о таблицах базы данных недоступна.','Size'=>'Размер','Engine'=>'Двигатель','Rows'=>'Строки','Collation'=>'Сравнение','Charset'=>'Кодировка','Total Database Size'=>'Общий размер базы данных','Not installed'=>'Не установлено','Active'=>'Активно','Inactive'=>'Неактивно','unknown'=>'неизвестно','License'=>'Лицензия','Free plugin not set for plugin family: %s'=>'Бесплатный плагин не установлен для семейства плагинов: %s','Pro plugin not set for plugin family: %s'=>'Профессиональный плагин не установлен для семейства плагинов: %s','License activation error. Please try again later or contact support for help.'=>'Ошибка активации лицензии. Пожалуйста, попробуйте позже или свяжитесь с поддержкой для получения помощи.','License deactivation error. Please try again later or contact support for help.'=>'Ошибка деактивации лицензии. Пожалуйста, попробуйте позже или свяжитесь с поддержкой для получения помощи.','This license is currently disabled. Please contact support for help.'=>'Эта лицензия в настоящее время отключена. Пожалуйста, свяжитесь с поддержкой для получения помощи.','This license has expired. Please contact support to renew it.'=>'Срок действия этой лицензии истек. Пожалуйста, свяжитесь с поддержкой для её продления.','This license key could not be activated. It may be invalid, blocked, or not authorized for this plugin. Please verify the key and contact PublishPress support if the problem continues.'=>'Эту лицензию нельзя активировать. Она может быть недействительной, заблокированной или не авторизованной для этого плагина. Пожалуйста, проверьте ключ и свяжитесь с поддержкой PublishPress, если проблема продолжится.','This license cannot be used for this plugin. Please contact support for help.'=>'Эта лицензия не может быть использована для этого плагина. Пожалуйста, свяжитесь с поддержкой для получения помощи.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'Эта лицензия не соответствует плагину, который вы пытаетесь активировать. Пожалуйста, свяжитесь с поддержкой для получения помощи.','License key does not match our records. Please contact support for assistance.'=>'Ключ лицензии не соответствует нашим записям. Пожалуйста, свяжитесь с поддержкой для получения помощи.','No license key provided. Please enter a valid license key.'=>'Ключ лицензии не предоставлен. Пожалуйста, введите действительный ключ лицензии.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'URL вашего сайта необходим для активации лицензии. Пожалуйста, введите действительный URL сайта, чтобы продолжить.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'Достигнут лимит активации лицензии. Пожалуйста, свяжитесь с поддержкой для обновления или деактивации на другом сайте.','This license cannot be activated. Please contact support for help.'=>'Эту лицензию нельзя активировать. Пожалуйста, свяжитесь с поддержкой для получения помощи.','License server error. Please try again later or contact support for help.'=>'Ошибка сервера лицензий. Пожалуйста, попробуйте позже или свяжитесь с поддержкой для получения помощи.','The license server returned an invalid response. Please try again later or contact support for help.'=>'Сервер лицензий вернул недействительный ответ. Пожалуйста, попробуйте позже или свяжитесь с поддержкой для получения помощи.','This license is inactive for this site. Please contact support for help.'=>'Эта лицензия неактивна для этого сайта. Пожалуйста, свяжитесь с поддержкой для получения помощи.','Plugin activation failed. Please try again later or contact support for help.'=>'Ошибка активации плагина. Пожалуйста, попробуйте позже или свяжитесь с поддержкой для получения помощи.','This action is not possible because the plugin is already installed.'=>'Это действие невозможно, так как плагин уже установлен.','Plugin deactivation failed. Please try again later or contact support for help.'=>'Ошибка деактивации плагина. Пожалуйста, попробуйте позже или свяжитесь с поддержкой для получения помощи.','Plugin family not found. Please contact support for help.'=>'Семейство плагинов не найдено. Пожалуйста, свяжитесь с поддержкой для получения помощи.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'Это действие невозможно, так как установлены как бесплатная, так и профессиональная версии. Пожалуйста, удалите одну из версий, чтобы продолжить.','Plugin installation failed. Please contact support for help.'=>'Ошибка установки плагина. Пожалуйста, свяжитесь с поддержкой для получения помощи.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'Это действие невозможно, так как плагин не активирован. Пожалуйста, активируйте плагин и попробуйте снова.','Plugin not found in our available plugins list. Please contact support for help.'=>'Плагин не найден в нашем списке доступных плагинов. Пожалуйста, свяжитесь с поддержкой для получения помощи.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'Это действие невозможно, так как плагин не установлен. Пожалуйста, установите плагин и попробуйте снова.','Unknown license server error. Please try again later or contact support for help.'=>'Неизвестная ошибка сервера лицензий. Пожалуйста, попробуйте позже или свяжитесь с поддержкой для получения помощи.','Sell digital products, programs, and services from your website.'=>'Продавайте цифровые продукты, программы и услуги с вашего сайта.','Create and manage tags, categories, and taxonomy terms.'=>'Создавайте и управляйте тегами, категориями и терминами таксономии.','Organize taxonomy terms into groups and display them in clouds, tabs, and lists.'=>'Организуйте термины таксономии в группы и отображайте их в облаках, вкладках и списках.','Define tasks that authors must complete before publishing.'=>'Определите задачи, которые авторы должны выполнить перед публикацией.','Control who can edit and view your content.'=>'Контролируйте, кто может редактировать и просматривать ваш контент.','Create, manage and display authors for your content.'=>'Создавайте, управляйте и отображайте авторов вашего контента.','All the tools you need to improve the block editor.'=>'Все инструменты, необходимые для улучшения блочного редактора.','Control your admin area and user roles.'=>'Контролируйте свою админ-панель и роли пользователей.','Schedule changes to your posts.'=>'Запланируйте изменения в ваших постах.','Organize, schedule, and plan your publishing.'=>'Организуйте, планируйте и управляйте вашей публикацией.','Approve and schedule new versions to your published posts.'=>'Утверждайте и планируйте новые версии ваших опубликованных постов.','Organize your posts into issues or series.'=>'Организуйте ваши посты в выпуски или серии.','Create custom URLs for your posts and external links.'=>'Создайте пользовательские URL для ваших постов и внешних ссылок.','Create custom statuses and publishing workflows.'=>'Создайте пользовательские статусы и рабочие процессы публикации.','Dependency "%s" not found in container.'=>'Зависимость "%s" не найдена в контейнере.','Error validating license: %s'=>'Ошибка проверки лицензии: %s','Error getting license info: %s'=>'Ошибка получения информации о лицензии: %s','The license server denied this request. This can happen when a license key or site has been blocked. Please contact PublishPress support for help.'=>'Сервер лицензий отказал в этом запросе. Это может произойти, если ключ лицензии или сайт были заблокированы. Пожалуйста, свяжитесь с поддержкой PublishPress для получения помощи.','Too many requests. Please try again later.'=>'Слишком много запросов. Пожалуйста, попробуйте позже.','An error occurred while processing your request.'=>'Произошла ошибка при обработке вашего запроса.','Template not found: %s'=>'Шаблон не найден: %s','Path cannot be empty'=>'Путь не может быть пустым','File extension cannot be empty'=>'Расширение файла не может быть пустым','Invalid file path: null byte detected'=>'Недопустимый путь к файлу: обнаружен нулевой байт','Invalid file path: directory traversal detected'=>'Недопустимый путь к файлу: обнаружен обход каталога','Invalid file path: parent directory does not exist: %s'=>'Недопустимый путь к файлу: родительский каталог не существует: %s','Invalid file path: unable to resolve path'=>'Недопустимый путь к файлу: невозможно разрешить путь','Invalid file path: operation not allowed outside permitted directories'=>'Недопустимый путь к файлу: операция не разрешена за пределами разрешенных каталогов','Download URL failed WordPress validation'=>'URL для загрузки не прошел проверку WordPress','Downloaded plugin file does not exist'=>'Загруженный файл плагина не существует','Downloaded plugin file is empty'=>'Загруженный файл плагина пуст','Cannot read downloaded plugin file'=>'Не удалось прочитать загруженный файл плагина','Downloaded file is not a valid ZIP archive. The download URL may be returning an error page.'=>'Загруженный файл не является допустимым ZIP-архивом. URL для загрузки может возвращать страницу с ошибкой.','Failed to unzip plugin file: %s'=>'Не удалось разархивировать файл плагина: %s','Failed to unzip plugin file'=>'Не удалось разархивировать файл плагина','Failed to activate plugin: %s'=>'Не удалось активировать плагин: %s','Resolve conflicts for network-active plugins from Network Admin.'=>'Разрешите конфликты для сетевых активных плагинов из Сетевого администратора.','Activation recovery failed. Both plugin copies were retained. Please restore the previous version from the Plugins screen.'=>'Восстановление активации не удалось. Обе копии плагина были сохранены. Пожалуйста, восстановите предыдущую версию на экране Плагинов.','The other plugin could not be deactivated.'=>'Другой плагин не удалось деактивировать.','The selected plugin did not remain active.'=>'Выбранный плагин не остался активным.','The selected plugin could not be activated. Neither copy was deleted and the previous activation settings were restored.'=>'Выбранный плагин не может быть активирован. Ни одна копия не была удалена, и предыдущие настройки активации были восстановлены.','Failed to delete plugin: %s'=>'Не удалось удалить плагин: %s','No update available for this plugin'=>'Нет доступных обновлений для этого плагина','Invalid update information for this plugin'=>'Недействительная информация об обновлении для этого плагина','Update package not available'=>'Пакет обновления недоступен','Failed to update plugin: %s'=>'Не удалось обновить плагин: %s','Plugin update failed'=>'Не удалось обновить плагин','Invalid download URL provided'=>'Предоставлен недействительный URL для загрузки','Download URL must use HTTP or HTTPS protocol'=>'URL для загрузки должен использовать протокол HTTP или HTTPS','Download URL is not from an allowed domain: %s'=>'URL для загрузки не принадлежит разрешенному домену: %s','Could not create a temporary package file'=>'Не удалось создать временный файл пакета','Failed to download plugin: %s'=>'Не удалось загрузить плагин: %s','The plugin package download failed'=>'Загрузка пакета плагина не удалась','Failed to get plugin information: %s'=>'Не удалось получить информацию о плагине: %s','MCP Adapter could not be installed or activated. Use the plugin page or contact your host.'=>'MCP Adapter не удалось установить или активировать. Используйте страницу плагина или свяжитесь с вашим хостом.','MCP Adapter activated.'=>'MCP Adapter активирован.','ERR'=>'ERR','.'=>'.']];